import math
from numbers import Real


def position_to_value(position, extent, minimum, maximum, orientation="vertical", right_to_left=False):
    for name, value in (("position", position), ("extent", extent)):
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError(f"{name} must be a real number")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
    for name, value in (("minimum", minimum), ("maximum", maximum)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an integer")
    if not isinstance(orientation, str):
        raise TypeError("orientation must be a string")
    if not isinstance(right_to_left, bool):
        raise TypeError("right_to_left must be boolean")
    if extent <= 0:
        raise ValueError("extent must be positive")
    if minimum > maximum:
        raise ValueError("minimum must not exceed maximum")
    if orientation not in ("vertical", "horizontal"):
        raise ValueError("invalid orientation")
    if minimum == maximum:
        return minimum

    fraction = min(1.0, max(0.0, position / extent))
    if orientation == "horizontal" and right_to_left:
        fraction = 1.0 - fraction
    scaled = minimum + fraction * (maximum - minimum)
    return round(scaled)

